import math

def D(n):
    """Calculates D(n) = n^3 + 4n^2 + 6n + 4."""
    return n**3 + 4*n**2 + 6*n + 4

def is_5_smooth(number):
    """Checks if a number is only composed of prime factors 2 and 5, and returns (a, b) if so."""
    if number <= 0:
        return False, False # Should not happen for n>=0

    a = 0  # exponent of 2
    b = 0  # exponent of 5
    temp = number

    while temp % 2 == 0:
        a += 1
        temp //= 2

    while temp % 5 == 0:
        b += 1
        temp //= 5

    if temp == 1:
        return True, (a, b)
    else:
        return False, (0, 0)

def check_divisibility(n):
    """Checks the main condition: D(n) | 20^(n+1)."""
    dn = D(n)

    is_smooth, factors = is_5_smooth(dn)

    if not is_smooth:
        return False, None

    a, b = factors

    # 20^(n+1) = (2^2 * 5)^(n+1) = 2^(2n+2) * 5^(n+1)
    max_a = 2 * n + 2
    max_b = n + 1

    # D(n) divides 20^(n+1) if and only if the exponent of each prime factor 
    # in D(n) is less than or equal to the exponent in 20^(n+1).
    if a <= max_a and b <= max_b:
        return True, dn
    else:
        return False, dn

solutions = []
print("--- Testing n up to 50 ---")
for n in range(51):
    works, dn_value = check_divisibility(n)
    if works:
        solutions.append(n)
        print(f"Solution found for n={n}. D(n) = {dn_value}.")
    elif n < 10 or n % 2 == 0: # Print a few more details for small/even n to confirm logic
        is_smooth, _ = is_5_smooth(D(n))
        if not is_smooth:
            print(f"n={n}: D(n)={D(n)} is NOT 5-smooth.")

print("\n--- Summary ---")
print(f"All solutions found up to n=50: {solutions}")

def is_5_smooth(N):
    if N <= 0:
        return False
    while N % 2 == 0:
        N //= 2
    while N % 5 == 0:
        N //= 5
    return N == 1

solutions = []
P_candidates = []

# Generate P = 2^a * 5^b such that P >= 2
a = 0
while True:
    P_candidates.append(2**a)
    a += 1

b = 0
while True:
    P = 2**b
    b += 1
    if P > 10000: # Upper bound check
        break

# Combine them and ensure uniqueness and ordering
P_set = set()
for pa in [2**i for i in range(15)]:
    for pb in [5**j for j in range(5)]:
        P = pa * pb
        if P >= 2 and P <= 10000 and P not in P_set:
            P_set.add(P)

P_sorted = sorted(list(P_set))

for P in P_sorted:
    n = P - 2
    if n < 0:
        continue

    # Calculate Q = P^2 - 2P + 2
    Q = P*P - 2*P + 2

    if is_5_smooth(Q):
        # If Q is 5-smooth, D(n) = P * Q is 5-smooth.
        solutions.append(n)

print("Found solutions n (based on 5-smoothness of D(n)):", solutions)

